function buddyx_child_enqueue_styles()
{
    wp_enqueue_style('buddyx-style', get_template_directory_uri() . '/style.css');
    wp_enqueue_style(
        'buddyx-child-style',
        get_stylesheet_directory_uri() . '/style.css',
        array('buddyx-style'),
        wp_get_theme()->get('Version')
    );

    $pmpro_css_path = get_stylesheet_directory() . '/assets-enishi/css/pt-pmpro.css';
    if (file_exists($pmpro_css_path)) {
        wp_enqueue_style(
            'pt-pmpro-style',
            get_stylesheet_directory_uri() . '/assets-enishi/css/pt-pmpro.css',
            array('buddyx-child-style'),
            filemtime($pmpro_css_path)
        );
    }

    // Load Tailwind CSS (with preflight disabled so existing BuddyX/BuddyNext styles remain intact)
    $req_uri = $_SERVER['REQUEST_URI'] ?? '';
    $is_profile_or_pmpro = (function_exists('pmpro_is_plugin_page') && pmpro_is_plugin_page())
        || (function_exists('bp_is_user') && bp_is_user())
        || (function_exists('buddynext_is_profile') && buddynext_is_profile())
        || is_page([
            'membership-account',
            'membership-levels',
            'membership-checkout',
            'membership-confirmation',
            'your-profile',
        ])
        || (bool) get_query_var('bn_profile_action', false)
        || (bool) get_query_var('bn_user', false)
        || (strpos($req_uri, '/members/') !== false)
        || (strpos($req_uri, '/profile') !== false)
        || (strpos($req_uri, '/@') !== false)
        || (strpos($req_uri, '/membership-') !== false);

    if ($is_profile_or_pmpro) {
        wp_enqueue_script(
            'pt-tailwind-cdn',
            'https://cdn.tailwindcss.com',
            array(),
            null,
            false
        );
        wp_add_inline_script(
            'pt-tailwind-cdn',
            'if (typeof tailwind !== "undefined") { tailwind.config = { corePlugins: { preflight: false } }; }',
            'after'
        );
    }

    wp_enqueue_script(
        'pt-google-login',
        get_stylesheet_directory_uri() . '/assets-enishi/js/pt-google-login.js',
        array(),
        filemtime(get_stylesheet_directory() . '/assets-enishi/js/pt-google-login.js'),
        true
    );
    wp_localize_script(
        'pt-google-login',
        'ptGoogleLoginData',
        array(
            'ajaxUrl' => admin_url('admin-ajax.php'),
        )
    );
}

