/**
 * =========================================================
 * CHANNEL -> VIDEO LIVESTREAM BACKEND & TEMPLATE ROUTING
 * =========================================================
 */

/**
 * Tự động khởi tạo trang Video (Channel -> Video) nếu chưa tồn tại và gán template page-pt-live.php
 */
add_action('init', function () {
    if (get_option('pt_channel_video_page_initialized_v1')) {
        return;
    }

    $video_page = get_page_by_path('video');
    if (!$video_page) {
        $page_id = wp_insert_post([
            'post_title'   => 'Video',
            'post_name'    => 'video',
            'post_status'  => 'publish',
            'post_type'    => 'page',
            'post_content' => '',
        ]);
        if ($page_id && !is_wp_error($page_id)) {
            update_post_meta($page_id, '_wp_page_template', 'page-pt-live.php');
        }
    } else {
        $current_tpl = get_post_meta($video_page->ID, '_wp_page_template', true);
        if (empty($current_tpl) || $current_tpl === 'default') {
            update_post_meta($video_page->ID, '_wp_page_template', 'page-pt-live.php');
        }
    }

    $channel_video_page = get_page_by_path('channel/video');
    if ($channel_video_page) {
        update_post_meta($channel_video_page->ID, '_wp_page_template', 'page-pt-live.php');
    }

    update_option('pt_channel_video_page_initialized_v1', 1);
}, 20);

/**
 * Đảm bảo mọi truy cập vào trang Channel -> Video (/video, /channel/video, /channel-video, /pt-live)
 * đều render giao diện Livestream (page-pt-live.php)
 */
add_filter('template_include', function ($template) {
    if (is_page(['video', 'channel-video', 'pt-live', 'live-stream', 'livestream'])) {
        $live_tpl = get_stylesheet_directory() . '/page-pt-live.php';
        if (file_exists($live_tpl)) {
            return $live_tpl;
        }
    }

    if (is_page()) {
        global $post;
        if ($post && in_array($post->post_name, ['video', 'channel-video', 'pt-live', 'livestream'], true)) {
            $live_tpl = get_stylesheet_directory() . '/page-pt-live.php';
            if (file_exists($live_tpl)) {
                return $live_tpl;
            }
        }
    }

    // Nếu URL là /channel/video hoặc /video nhưng trang chưa tạo kịp trong DB
    $req_uri = isset($_SERVER['REQUEST_URI']) ? trim((string) parse_url(wp_unslash($_SERVER['REQUEST_URI']), PHP_URL_PATH), '/') : '';
    if (in_array($req_uri, ['video', 'channel/video', 'channel-video'], true) && is_404()) {
        status_header(200);
        global $wp_query;
        $wp_query->is_404  = false;
        $wp_query->is_page = true;
        $live_tpl = get_stylesheet_directory() . '/page-pt-live.php';
        if (file_exists($live_tpl)) {
            return $live_tpl;
        }
    }

    return $template;
}, 99);

/**
 * Lấy danh sách các kênh đang phát trực tiếp (kèm các kênh mẫu của cộng đồng)
 */
function pt_get_active_livestreams_list()
{
    $stored = get_option('pt_active_livestreams', []);
    if (!is_array($stored)) {
        $stored = [];
    }

    $now     = time();
    $cleaned = [];

    foreach ($stored as $room => $info) {
        if (!is_array($info)) {
            continue;
        }
        $updated = isset($info['updated_at']) ? (int) $info['updated_at'] : 0;
        // Giữ các kênh còn heartbeat trong 45 giây gần nhất (heartbeat mỗi 15s)
        if ($now - $updated <= 45) {
            $cleaned[$room] = $info;
        }
    }

    if (count($cleaned) !== count($stored)) {
        update_option('pt_active_livestreams', $cleaned, false);
    }

    return array_values($cleaned);
}

add_action('wp_ajax_pt_live_start_stream', 'pt_live_start_stream_ajax');
function pt_live_start_stream_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $user          = wp_get_current_user();
    $room          = sanitize_text_field(wp_unslash($_POST['room'] ?? ('channel-' . $user->ID)));
    $title         = sanitize_text_field(wp_unslash($_POST['title'] ?? ($user->display_name . ' is live now')));
    $category      = sanitize_text_field(wp_unslash($_POST['category'] ?? 'Talk & Hangout'));
    $place_id      = sanitize_text_field(wp_unslash($_POST['place_id'] ?? ''));
    $place_name    = sanitize_text_field(wp_unslash($_POST['place_name'] ?? ''));
    $place_address = sanitize_text_field(wp_unslash($_POST['place_address'] ?? ''));
    $hls_url       = esc_url_raw(wp_unslash($_POST['hls_url'] ?? ''));
    if ($hls_url === '' && defined('PT_LIVE_HLS_BASE_URL') && PT_LIVE_HLS_BASE_URL) {
        $hls_url = trailingslashit(PT_LIVE_HLS_BASE_URL) . rawurlencode($room) . '/index.m3u8';
    }
    $avatar        = get_avatar_url($user->ID, ['size' => 128]);

    $stored = get_option('pt_active_livestreams', []);
    if (!is_array($stored)) {
        $stored = [];
    }

    $stored[$room] = [
        'room'          => $room,
        'title'         => $title,
        'category'      => $category,
        'hls_url'       => $hls_url,
        'place_id'      => $place_id,
        'place_name'    => $place_name,
        'place_address' => $place_address,
        'host_id'       => (int) $user->ID,
        'host_name'     => $user->display_name ?: $user->user_login,
        'host_avatar'   => $avatar,
        'thumb'         => $avatar,
        'viewers'       => 1,
        'is_live'       => true,
        'started_at'    => time(),
        'updated_at'    => time(),
    ];

    update_option('pt_active_livestreams', $stored, false);

    wp_send_json_success([
        'stream'  => $stored[$room],
        'streams' => pt_get_active_livestreams_list(),
    ]);
}

add_action('wp_ajax_pt_live_heartbeat', 'pt_live_heartbeat_ajax');
function pt_live_heartbeat_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $room    = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $viewers = max(1, intval($_POST['viewers'] ?? 1));
    if ($room !== '') {
        $viewers = max($viewers, pt_live_count_active_viewers($room));
    }

    $stored = get_option('pt_active_livestreams', []);
    if (is_array($stored) && isset($stored[$room])) {
        $stored[$room]['updated_at'] = time();
        $stored[$room]['viewers']    = $viewers;
        update_option('pt_active_livestreams', $stored, false);
    }

    wp_send_json_success(['ok' => true, 'viewers' => $viewers]);
}

add_action('wp_ajax_pt_live_stop_stream', 'pt_live_stop_stream_ajax');
function pt_live_stop_stream_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $room   = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $stored = get_option('pt_active_livestreams', []);
    if (is_array($stored) && isset($stored[$room])) {
        unset($stored[$room]);
        update_option('pt_active_livestreams', $stored, false);
    }

    if ($room !== '') {
        pt_live_cleanup_room_chunks($room);
    }

    wp_send_json_success([
        'streams' => pt_get_active_livestreams_list(),
    ]);
}

function pt_live_get_chunks_dir($room)
{
    $upload = wp_upload_dir();
    $slug   = sanitize_key($room ?: 'default');
    return [
        'dir' => trailingslashit($upload['basedir']) . 'pt-live-chunks/' . $slug,
        'url' => trailingslashit($upload['baseurl']) . 'pt-live-chunks/' . $slug,
    ];
}

function pt_live_cleanup_room_chunks($room)
{
    $paths = pt_live_get_chunks_dir($room);
    if (!is_dir($paths['dir'])) {
        return;
    }
    $files = glob($paths['dir'] . '/*');
    if (is_array($files)) {
        foreach ($files as $file) {
            if (is_file($file)) {
                @unlink($file);
            }
        }
    }
    @rmdir($paths['dir']);
}

add_action('wp_ajax_pt_live_push_chunk', 'pt_live_push_chunk_ajax');
function pt_live_push_chunk_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $room = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $seq  = max(0, intval($_POST['seq'] ?? 0));
    $mime = sanitize_text_field(wp_unslash($_POST['mime'] ?? 'video/webm'));

    if ($room === '' || empty($_FILES['chunk']['tmp_name'])) {
        wp_send_json_error(['message' => 'Missing chunk data'], 400);
    }

    $paths = pt_live_get_chunks_dir($room);
    if (!is_dir($paths['dir'])) {
        wp_mkdir_p($paths['dir']);
    }

    $ext      = strpos($mime, 'mp4') !== false ? 'mp4' : 'webm';
    $filename = sprintf('chunk_%06d.%s', $seq, $ext);
    $dest     = $paths['dir'] . '/' . $filename;

    if (!@move_uploaded_file($_FILES['chunk']['tmp_name'], $dest)) {
        wp_send_json_error(['message' => 'Failed to save chunk'], 500);
    }

    $manifest_file = $paths['dir'] . '/manifest.json';
    $manifest      = ['mime' => $mime, 'updated_at' => time(), 'chunks' => []];
    if (is_file($manifest_file)) {
        $decoded = json_decode((string) file_get_contents($manifest_file), true);
        if (is_array($decoded) && !empty($decoded['chunks'])) {
            $manifest['chunks'] = $decoded['chunks'];
        }
    }

    $manifest['mime']       = $mime;
    $manifest['updated_at'] = time();
    $manifest['chunks'][]   = [
        'seq' => $seq,
        'url' => $paths['url'] . '/' . $filename,
        'ts'  => time(),
    ];

    // Always preserve chunk 0 (WebM initialization segment) so late-joining viewers can decode video,
    // and keep the latest 12 media chunks (~24s window).
    if (count($manifest['chunks']) > 13) {
        $has_init = isset($manifest['chunks'][0]['seq']) && (int) $manifest['chunks'][0]['seq'] === 0;
        $offset   = $has_init ? 1 : 0;
        $removed  = array_splice($manifest['chunks'], $offset, count($manifest['chunks']) - 13);
        foreach ($removed as $old) {
            if (!empty($old['url'])) {
                $old_path = $paths['dir'] . '/' . basename($old['url']);
                if (is_file($old_path)) {
                    @unlink($old_path);
                }
            }
        }
    }

    file_put_contents($manifest_file, wp_json_encode($manifest));

    // Also refresh stream heartbeat timestamp
    $stored = get_option('pt_active_livestreams', []);
    if (is_array($stored) && isset($stored[$room])) {
        $stored[$room]['updated_at'] = time();
        update_option('pt_active_livestreams', $stored, false);
    }

    wp_send_json_success(['seq' => $seq]);
}

add_action('wp_ajax_pt_live_get_chunks', 'pt_live_get_chunks_ajax');
add_action('wp_ajax_nopriv_pt_live_get_chunks', 'pt_live_get_chunks_ajax');
function pt_live_get_chunks_ajax()
{
    $room = sanitize_text_field(wp_unslash($_REQUEST['room'] ?? ''));
    if ($room === '') {
        wp_send_json_success(['active' => false, 'chunks' => []]);
    }

    $paths         = pt_live_get_chunks_dir($room);
    $manifest_file = $paths['dir'] . '/manifest.json';
    if (!is_file($manifest_file)) {
        wp_send_json_success(['active' => false, 'chunks' => []]);
    }

    $manifest = json_decode((string) file_get_contents($manifest_file), true);
    if (!is_array($manifest) || (time() - (int) ($manifest['updated_at'] ?? 0)) > 45) {
        wp_send_json_success(['active' => false, 'chunks' => []]);
    }

    wp_send_json_success([
        'active' => true,
        'mime'   => $manifest['mime'] ?? 'video/webm',
        'chunks' => $manifest['chunks'] ?? [],
    ]);
}

add_action('wp_ajax_pt_live_push_frame', 'pt_live_push_frame_ajax');
function pt_live_push_frame_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $room = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    if ($room === '' || empty($_FILES['frame']['tmp_name'])) {
        wp_send_json_error(['message' => 'Missing frame'], 400);
    }

    $paths = pt_live_get_chunks_dir($room);
    if (!is_dir($paths['dir'])) {
        wp_mkdir_p($paths['dir']);
    }

    $dest = $paths['dir'] . '/latest.jpg';
    if (!@move_uploaded_file($_FILES['frame']['tmp_name'], $dest)) {
        wp_send_json_error(['message' => 'Failed to save frame'], 500);
    }

    wp_send_json_success(['url' => $paths['url'] . '/latest.jpg']);
}

function pt_live_count_active_viewers($room, $add_viewer_id = '')
{
    $key = 'pt_live_viewers_' . md5($room);
    $viewers = get_transient($key);
    if (!is_array($viewers)) {
        $viewers = [];
    }
    $now = time();
    foreach ($viewers as $vid => $ts) {
        if (($now - (int) $ts) > 20) {
            unset($viewers[$vid]);
        }
    }
    if ($add_viewer_id !== '') {
        $viewers[$add_viewer_id] = $now;
    }
    set_transient($key, $viewers, 60);
    return count($viewers) + 1;
}

