/**
 * PeerJS Zoom-like Group Meeting Room Sync, Leave & Chat
 */
add_action('wp_ajax_pt_meet_sync', 'pt_ajax_meet_sync');
add_action('wp_ajax_nopriv_pt_meet_sync', 'pt_ajax_meet_sync');
function pt_ajax_meet_sync()
{
    $room      = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $peer_id   = sanitize_text_field(wp_unslash($_POST['peer_id'] ?? ''));
    $user_name = sanitize_text_field(wp_unslash($_POST['user_name'] ?? 'Guest'));
    $avatar    = esc_url_raw(wp_unslash($_POST['avatar'] ?? ''));
    $mic_on    = !empty($_POST['mic_on']) && $_POST['mic_on'] === '1';
    $cam_on    = !empty($_POST['cam_on']) && $_POST['cam_on'] === '1';

    if ($room === '' || $peer_id === '') {
        wp_send_json_error(['message' => 'Missing room or peer_id']);
    }

    $room_hash = md5($room);
    $peers_key = 'pt_meet_peers_' . $room_hash;
    $chat_key  = 'pt_meet_chat_' . $room_hash;

    $peers = get_transient($peers_key);
    if (!is_array($peers)) {
        $peers = [];
    }

    $now = time();
    foreach ($peers as $pid => $info) {
        if (!is_array($info) || ($now - (int) ($info['updated_at'] ?? 0)) > 20) {
            unset($peers[$pid]);
        }
    }

    $peers[$peer_id] = [
        'peer_id'    => $peer_id,
        'user_name'  => $user_name ?: 'Guest',
        'avatar'     => $avatar,
        'mic_on'     => $mic_on,
        'cam_on'     => $cam_on,
        'updated_at' => $now,
    ];

    set_transient($peers_key, $peers, 60);

    $messages = get_transient($chat_key);
    if (!is_array($messages)) {
        $messages = [];
    }

    wp_send_json_success([
        'peers'    => array_values($peers),
        'messages' => $messages,
    ]);
}

add_action('wp_ajax_pt_meet_leave', 'pt_ajax_meet_leave');
add_action('wp_ajax_nopriv_pt_meet_leave', 'pt_ajax_meet_leave');
function pt_ajax_meet_leave()
{
    $room    = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $peer_id = sanitize_text_field(wp_unslash($_POST['peer_id'] ?? ''));

    if ($room !== '' && $peer_id !== '') {
        $peers_key = 'pt_meet_peers_' . md5($room);
        $peers     = get_transient($peers_key);
        if (is_array($peers) && isset($peers[$peer_id])) {
            unset($peers[$peer_id]);
            set_transient($peers_key, $peers, 60);
        }
    }

    wp_send_json_success(['left' => true]);
}

add_action('wp_ajax_pt_meet_chat', 'pt_ajax_meet_chat');
add_action('wp_ajax_nopriv_pt_meet_chat', 'pt_ajax_meet_chat');
function pt_ajax_meet_chat()
{
    $room      = sanitize_text_field(wp_unslash($_POST['room'] ?? ''));
    $user_name = sanitize_text_field(wp_unslash($_POST['user_name'] ?? 'Guest'));
    $text      = trim(sanitize_text_field(wp_unslash($_POST['text'] ?? '')));

    if ($room === '' || $text === '') {
        wp_send_json_error(['message' => 'Missing room or message']);
    }

    $chat_key = 'pt_meet_chat_' . md5($room);
    $messages = get_transient($chat_key);
    if (!is_array($messages)) {
        $messages = [];
    }

    $messages[] = [
        'user_name' => $user_name ?: 'Guest',
        'text'      => $text,
        'time'      => current_time('H:i'),
    ];
    if (count($messages) > 100) {
        $messages = array_slice($messages, -100);
    }

    set_transient($chat_key, $messages, HOUR_IN_SECONDS);

    wp_send_json_success(['messages' => $messages]);
}

/**
 * Save recorded livestream video to /root/enishi2026/wpenishi/wp-content/uploads/
 * Filename format: yyyymmddhhmmss_username.webm
 */
add_action('wp_ajax_pt_live_save_recording', 'pt_ajax_live_save_recording');
function pt_ajax_live_save_recording()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    if (empty($_FILES['video']) || !empty($_FILES['video']['error'])) {
        wp_send_json_error(['message' => 'No video file uploaded'], 400);
    }

    $user      = wp_get_current_user();
    $username  = sanitize_file_name($user->user_login ?: ($user->display_name ?: 'user_' . $user->ID));
    $timestamp = current_time('YmdHis');
    $filename  = $timestamp . '_' . $username . '.webm';

    $target_dir = '/root/enishi2026/wpenishi/wp-content/uploads';
    if (!is_dir($target_dir) || !is_writable($target_dir)) {
        $upload_dir = wp_upload_dir();
        $target_dir = rtrim((string) ($upload_dir['basedir'] ?? WP_CONTENT_DIR . '/uploads'), '/');
    }

    if (!is_dir($target_dir)) {
        wp_mkdir_p($target_dir);
    }

    $target_path = trailingslashit($target_dir) . $filename;
    if (!@move_uploaded_file($_FILES['video']['tmp_name'], $target_path)) {
        wp_send_json_error(['message' => 'Failed to save video file'], 500);
    }

    $upload_dir = wp_upload_dir();
    $file_url   = trailingslashit((string) ($upload_dir['baseurl'] ?? content_url('/uploads'))) . $filename;

    wp_send_json_success([
        'filename' => $filename,
        'path'     => $target_path,
        'url'      => $file_url,
    ]);
}

/**
 * Kiểm tra user có gói PMPro trả phí (không phải free) hay không.
 */
function pt_user_has_paid_pmpro($user_id)
{
    $user_id = (int) $user_id;
    if ($user_id <= 0 || !function_exists('pmpro_getMembershipLevelsForUser')) {
        return false;
    }
    $levels = pmpro_getMembershipLevelsForUser($user_id);
    if (empty($levels) || !is_array($levels)) {
        return false;
    }
    foreach ($levels as $level) {
        if ((float) ($level->initial_payment ?? 0) > 0 || (float) ($level->billing_amount ?? 0) > 0) {
            return true;
        }
    }
    return false;
}

/**
 * Trả về inbox đã áp dụng giới hạn: tài khoản free chỉ đọc được tin nhắn đầu tiên (cũ nhất),
 * các tin còn lại bị che nội dung ngay từ server.
 */
function pt_get_place_inbox_for_viewer($user_id)
{
    $inbox = get_user_meta((int) $user_id, 'pt_place_inbox_messages', true);
    if (!is_array($inbox)) {
        $inbox = [];
    }
    $is_paid = pt_user_has_paid_pmpro($user_id);
    $total   = count($inbox);
    foreach ($inbox as $i => $msg) {
        // Inbox lưu mới nhất ở đầu => tin nhắn đầu tiên nhận được là phần tử cuối
        $is_first = ($i === $total - 1);
        $inbox[$i]['locked'] = (!$is_paid && !$is_first);
        if ($inbox[$i]['locked']) {
            $inbox[$i]['subject'] = '';
            $inbox[$i]['message'] = '';
        }
    }
    return [
        'messages' => $inbox,
        'is_paid'  => $is_paid,
        'upgrade_url' => function_exists('pmpro_url') ? pmpro_url('levels') : home_url('/membership-levels/'),
    ];
}

add_action('wp_ajax_pt_get_place_inbox_messages', 'pt_get_place_inbox_messages_ajax');
function pt_get_place_inbox_messages_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }
    wp_send_json_success(pt_get_place_inbox_for_viewer(get_current_user_id()));
}

/**
 * Reply lại tin nhắn trong Message (nếu người gửi có trong hệ thống thì gửi tin nhắn kèm tin nhắn cũ lại cho người đó).
 */
add_action('wp_ajax_pt_reply_place_inbox_message', 'pt_reply_place_inbox_message_ajax');
function pt_reply_place_inbox_message_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    $current_user_id = get_current_user_id();
    $message_id      = sanitize_text_field(wp_unslash($_POST['message_id'] ?? ''));
    $reply_text      = trim(sanitize_textarea_field(wp_unslash($_POST['reply_text'] ?? '')));

    if ($message_id === '' || $reply_text === '') {
        wp_send_json_error(['message' => 'Vui lòng nhập nội dung trả lời.'], 400);
    }

    $inbox = get_user_meta($current_user_id, 'pt_place_inbox_messages', true);
    if (!is_array($inbox) || empty($inbox)) {
        wp_send_json_error(['message' => 'Không tìm thấy tin nhắn gốc.'], 404);
    }

    $orig_index = null;
    $orig_msg   = null;
    $total      = count($inbox);
    $is_paid    = pt_user_has_paid_pmpro($current_user_id);

    foreach ($inbox as $i => $msg) {
        if (($msg['id'] ?? '') === $message_id) {
            $is_first = ($i === $total - 1);
            if (!$is_paid && !$is_first) {
                wp_send_json_error(['message' => 'Tài khoản Free không thể trả lời tin nhắn bị khóa.'], 403);
            }
            $orig_index = $i;
            $orig_msg   = $msg;
            break;
        }
    }

    if ($orig_msg === null) {
        wp_send_json_error(['message' => 'Không tìm thấy tin nhắn gốc.'], 404);
    }

    $target_user_id = (int) ($orig_msg['sender_id'] ?? 0);
    $target_user    = $target_user_id > 0 ? get_userdata($target_user_id) : false;

    if (!$target_user) {
        wp_send_json_error(['message' => 'Người gửi không còn tồn tại trong hệ thống.'], 404);
    }

    $current_user   = get_userdata($current_user_id);
    $sender_name    = $current_user ? ($current_user->display_name ?: $current_user->user_login) : ('User #' . $current_user_id);
    $old_message    = (string) ($orig_msg['message'] ?? '');
    $orig_subject   = (string) ($orig_msg['subject'] ?? '');
    $reply_subject  = $orig_subject !== '' ? 'Re: ' . $orig_subject : 'Re: Tin nhắn';
    $combined_msg   = $reply_text . "\n\n--- Tin nhắn cũ ---\n" . $old_message;
    $now            = current_time('mysql');

    // Gửi tin nhắn kèm tin nhắn cũ vào hộp thư Message của người gửi ban đầu
    $target_inbox = get_user_meta($target_user_id, 'pt_place_inbox_messages', true);
    if (!is_array($target_inbox)) {
        $target_inbox = [];
    }

    array_unshift($target_inbox, [
        'id'             => uniqid('ptm_', true),
        'sender_id'      => $current_user_id,
        'sender_name'    => $sender_name,
        'place_name'     => (string) ($orig_msg['place_name'] ?? ''),
        'address'        => (string) ($orig_msg['address'] ?? ''),
        'subject'        => $reply_subject,
        'message'        => $combined_msg,
        'reply_to_id'    => $message_id,
        'quoted_message' => $old_message,
        'created_at'     => $now,
    ]);
    update_user_meta($target_user_id, 'pt_place_inbox_messages', array_slice($target_inbox, 0, 100));

    // Đánh dấu tin nhắn gốc đã được trả lời
    $inbox[$orig_index]['replied']    = true;
    $inbox[$orig_index]['reply_text'] = $reply_text;
    $inbox[$orig_index]['replied_at'] = $now;
    update_user_meta($current_user_id, 'pt_place_inbox_messages', $inbox);

    // Gửi thông báo BuddyNext nếu có
    $recipient_messages_url = function_exists('pt_get_user_messages_profile_url') ? pt_get_user_messages_profile_url($target_user_id) : home_url('/members/' . ($target_user ? $target_user->user_nicename : '') . '/messages/');
    $notif_msg = sprintf('%s replied to your message: %s', $sender_name, wp_trim_words($reply_text, 15));
    if (function_exists('buddynext_service')) {
        try {
            $notif_svc = buddynext_service('notifications');
            if (is_object($notif_svc) && method_exists($notif_svc, 'create')) {
                $notif_svc->create([
                    'recipient_id' => $target_user_id,
                    'actor_id'     => $current_user_id,
                    'sender_id'    => $current_user_id,
                    'type'         => 'message',
                    'object_type'  => 'message_reply',
                    'object_id'    => 0,
                    'data'         => [
                        'url'     => $recipient_messages_url,
                        'message' => $notif_msg,
                    ],
                    'url'          => $recipient_messages_url,
                    'title'        => $reply_subject,
                    'message'      => $notif_msg,
                    'body'         => wp_trim_words($reply_text, 20),
                ]);
            }
        } catch (\Throwable $e) {}
    }
    if (function_exists('bp_notifications_add_notification')) {
        bp_notifications_add_notification([
            'user_id'           => $target_user_id,
            'item_id'           => $current_user_id,
            'secondary_item_id' => $current_user_id,
            'component_name'    => 'messages',
            'component_action'  => 'new_message',
            'date_notified'     => bp_core_current_time(),
            'is_new'            => 1,
        ]);
    }

    wp_send_json_success([
        'message'    => 'Đã gửi phản hồi kèm tin nhắn cũ cho ' . ($target_user->display_name ?: $target_user->user_login) . '!',
        'replied_at' => $now,
    ]);
}

/**
 * TH1: Gửi tin nhắn trực tiếp từ trang Profile của người khác (Người A -> Người B).
 */
add_action('wp_ajax_pt_send_profile_message', 'pt_send_profile_message_ajax');
function pt_send_profile_message_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Vui lòng đăng nhập để gửi tin nhắn.'], 403);
    }

    $sender_id    = get_current_user_id();
    $recipient_id = isset($_POST['recipient_id']) ? (int) $_POST['recipient_id'] : 0;
    $subject      = sanitize_text_field(wp_unslash($_POST['subject'] ?? ''));
    $message      = trim(sanitize_textarea_field(wp_unslash($_POST['message'] ?? '')));

    if ($recipient_id <= 0 || $recipient_id === $sender_id) {
        wp_send_json_error(['message' => 'Người nhận không hợp lệ.'], 400);
    }

    $recipient_user = get_userdata($recipient_id);
    if (!$recipient_user) {
        wp_send_json_error(['message' => 'Người nhận không tồn tại trong hệ thống.'], 404);
    }

    if ($message === '') {
        wp_send_json_error(['message' => 'Vui lòng nhập nội dung tin nhắn.'], 400);
    }

    $sender_user = get_userdata($sender_id);
    $sender_name = $sender_user ? ($sender_user->display_name ?: $sender_user->user_login) : ('User #' . $sender_id);
    $now         = current_time('mysql');

    $inbox = get_user_meta($recipient_id, 'pt_place_inbox_messages', true);
    if (!is_array($inbox)) {
        $inbox = [];
    }

    array_unshift($inbox, [
        'id'          => uniqid('ptm_', true),
        'sender_id'   => $sender_id,
        'sender_name' => $sender_name,
        'place_name'  => '',
        'address'     => '',
        'subject'     => $subject !== '' ? $subject : 'Tin nhắn từ ' . $sender_name,
        'message'     => $message,
        'created_at'  => $now,
    ]);
    update_user_meta($recipient_id, 'pt_place_inbox_messages', array_slice($inbox, 0, 100));

    if (function_exists('buddynext_service')) {
        try {
            $notif_svc = buddynext_service('notifications');
            if (is_object($notif_svc) && method_exists($notif_svc, 'create')) {
                $recipient_messages_url = function_exists('pt_get_user_messages_profile_url') ? pt_get_user_messages_profile_url($recipient_id) : home_url('/members/' . ($recipient_user ? $recipient_user->user_nicename : '') . '/messages/');
                $notif_msg = sprintf('%s sent you a message: %s', $sender_name, wp_trim_words($message, 15));
                $notif_svc->create([
                    'recipient_id' => $recipient_id,
                    'actor_id'     => $sender_id,
                    'sender_id'    => $sender_id,
                    'type'         => 'message',
                    'object_type'  => 'profile_message',
                    'object_id'    => 0,
                    'data'         => [
                        'url'     => $recipient_messages_url,
                        'message' => $notif_msg,
                    ],
                    'url'          => $recipient_messages_url,
                    'title'        => $subject !== '' ? $subject : 'New message',
                    'message'      => $notif_msg,
                    'body'         => wp_trim_words($message, 20),
                ]);
            }
        } catch (\Throwable $e) {}
    }
    if (function_exists('bp_notifications_add_notification')) {
        bp_notifications_add_notification([
            'user_id'           => $recipient_id,
            'item_id'           => $sender_id,
            'secondary_item_id' => $sender_id,
            'component_name'    => 'messages',
            'component_action'  => 'new_message',
            'date_notified'     => bp_core_current_time(),
            'is_new'            => 1,
        ]);
    }

    wp_send_json_success([
        'message' => 'Đã gửi tin nhắn tới ' . ($recipient_user->display_name ?: $recipient_user->user_login) . '!',
    ]);
}

/**
 * Hiển thị nút "Gửi tin nhắn" + Modal khi xem Profile của người khác (TH1).
 */
add_action('buddynext_part_profile_tab_panel_after', 'pt_render_profile_send_message_widget');
function pt_render_profile_send_message_widget($args)
{
    if (!is_user_logged_in()) {
        return;
    }
    $profile_user_id = (int) ($args['profile_user_id'] ?? 0);
    $viewer_id       = (int) ($args['viewer_id'] ?? get_current_user_id());
    if ($profile_user_id <= 0 || $viewer_id <= 0 || $profile_user_id === $viewer_id) {
        return;
    }
    $target_user = get_userdata($profile_user_id);
    if (!$target_user) {
        return;
    }
    $target_name = $target_user->display_name ?: $target_user->user_login;
    $ajax_url    = admin_url('admin-ajax.php');
    ?>
    <div style="margin:12px 0;display:flex;justify-content:flex-end;">
        <button type="button" id="pt-open-profile-msg-btn" style="background:#2563eb;color:#fff;border:none;border-radius:8px;padding:8px 16px;font-size:13px;font-weight:600;cursor:pointer;">
            💬 Gửi tin nhắn cho <?php echo esc_html($target_name); ?>
        </button>
    </div>

    <div id="pt-profile-msg-modal" style="display:none;position:fixed;inset:0;z-index:99999;background:rgba(15,23,42,0.55);align-items:center;justify-content:center;padding:16px;">
        <div style="background:#fff;border-radius:14px;max-width:460px;width:100%;padding:20px;box-shadow:0 20px 40px rgba(0,0,0,0.2);">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
                <h3 style="margin:0;font-size:16px;font-weight:700;color:#0f172a;">Gửi tin nhắn cho <?php echo esc_html($target_name); ?></h3>
                <button type="button" id="pt-close-profile-msg-btn" style="background:none;border:none;font-size:22px;line-height:1;color:#64748b;cursor:pointer;">&times;</button>
            </div>
            <form id="pt-profile-msg-form">
                <input type="hidden" name="recipient_id" value="<?php echo esc_attr((string) $profile_user_id); ?>" />
                <div style="margin-bottom:10px;">
                    <input type="text" id="pt-pm-subject" name="subject" placeholder="Tiêu đề (tùy chọn)" style="width:100%;padding:9px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;box-sizing:border-box;" />
                </div>
                <div style="margin-bottom:12px;">
                    <textarea id="pt-pm-message" name="message" rows="4" required placeholder="Nhập nội dung tin nhắn..." style="width:100%;padding:9px 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:13px;resize:vertical;box-sizing:border-box;"></textarea>
                </div>
                <div style="display:flex;justify-content:flex-end;gap:8px;">
                    <button type="button" id="pt-cancel-profile-msg-btn" style="background:#f1f5f9;border:1px solid #cbd5e1;color:#334155;padding:8px 14px;border-radius:8px;font-size:13px;cursor:pointer;">Hủy</button>
                    <button type="submit" id="pt-submit-profile-msg-btn" style="background:#2563eb;border:none;color:#fff;padding:8px 18px;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;">Gửi tin nhắn</button>
                </div>
            </form>
        </div>
    </div>

    <script>
    (function () {
        const openBtn = document.getElementById('pt-open-profile-msg-btn');
        const modal = document.getElementById('pt-profile-msg-modal');
        const closeBtn = document.getElementById('pt-close-profile-msg-btn');
        const cancelBtn = document.getElementById('pt-cancel-profile-msg-btn');
        const form = document.getElementById('pt-profile-msg-form');
        const submitBtn = document.getElementById('pt-submit-profile-msg-btn');
        if (!openBtn || !modal || !form) return;

        const closeModal = () => { modal.style.display = 'none'; };
        openBtn.addEventListener('click', () => { modal.style.display = 'flex'; });
        if (closeBtn) closeBtn.addEventListener('click', closeModal);
        if (cancelBtn) cancelBtn.addEventListener('click', closeModal);
        modal.addEventListener('click', (e) => { if (e.target === modal) closeModal(); });

        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const msgEl = document.getElementById('pt-pm-message');
            const subEl = document.getElementById('pt-pm-subject');
            const text = (msgEl.value || '').trim();
            if (!text) return;

            submitBtn.disabled = true;
            submitBtn.textContent = 'Đang gửi...';
            try {
                const fd = new FormData();
                fd.append('action', 'pt_send_profile_message');
                fd.append('recipient_id', form.querySelector('[name="recipient_id"]').value);
                fd.append('subject', subEl.value || '');
                fd.append('message', text);
                const res = await fetch(<?php echo wp_json_encode($ajax_url); ?>, { method: 'POST', credentials: 'same-origin', body: fd });
                const json = await res.json();
                if (json && json.success) {
                    alert(json.data.message || 'Đã gửi tin nhắn!');
                    msgEl.value = '';
                    subEl.value = '';
                    closeModal();
                } else {
                    alert((json && json.data && json.data.message) || 'Không thể gửi tin nhắn.');
                }
            } catch (err) {
                alert('Lỗi kết nối, vui lòng thử lại.');
            } finally {
                submitBtn.disabled = false;
                submitBtn.textContent = 'Gửi tin nhắn';
            }
        });
    })();
    </script>
    <?php
}

add_action('wp_ajax_pt_get_user_shop_info', 'pt_get_user_shop_info_ajax');
function pt_get_user_shop_info_ajax()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Login required'], 403);
    }

    global $wpdb;
    $target_user_id = intval($_POST['user_id'] ?? $_GET['user_id'] ?? 0);
    $thread_id      = intval($_POST['thread_id'] ?? $_GET['thread_id'] ?? 0);

    if ($target_user_id <= 0 && $thread_id > 0) {
        $me = get_current_user_id();
        $msg_table = $wpdb->prefix . 'bn_messages_recipients';
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $msg_table)) === $msg_table) {
            $target_user_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT user_id FROM {$msg_table} WHERE thread_id = %d AND user_id != %d LIMIT 1",
                $thread_id,
                $me
            ));
        }
    }

    if ($target_user_id <= 0) {
        wp_send_json_error(['message' => 'User not found'], 404);
    }

    // 1. Lấy email từ bảng eni_users ($wpdb->users) và Basic Info (BuddyNext)
    $email = (string) $wpdb->get_var($wpdb->prepare(
        "SELECT user_email FROM {$wpdb->users} WHERE ID = %d LIMIT 1",
        $target_user_id
    ));
    $company  = '';
    $location = '';

    if (class_exists('\\BuddyNext\\Profile\\ProfileService')) {
        $profile_groups = \BuddyNext\Profile\ProfileService::get_profile($target_user_id, $target_user_id);
        if (is_array($profile_groups)) {
            foreach ($profile_groups as $grp) {
                $gkey = $grp['group_key'] ?? '';
                if ($gkey === 'basic_info' && !empty($grp['fields']) && is_array($grp['fields'])) {
                    foreach ($grp['fields'] as $f) {
                        $fkey = $f['field_key'] ?? '';
                        if ($fkey === 'email' && !empty($f['value'])) {
                            $email = (string) $f['value'];
                        }
                        if ($fkey === 'location' && !empty($f['value'])) {
                            $location = (string) $f['value'];
                        }
                    }
                }
                if ($gkey === 'work_experience' && !empty($grp['entries']) && is_array($grp['entries'])) {
                    foreach ($grp['entries'] as $entry) {
                        if (!is_array($entry)) continue;
                        foreach ($entry as $f) {
                            if (is_array($f) && ($f['field_key'] ?? '') === 'company' && !empty($f['value'])) {
                                $company = (string) $f['value'];
                                break 2;
                            }
                        }
                    }
                }
            }
        }
    }

    $parts = array_filter([$company, $location], static fn($v) => trim((string) $v) !== '');
    $query = !empty($parts) ? implode(' ', $parts) : trim($email);
    $map_url = $query !== '' ? add_query_arg('search', $query, home_url('/maps/')) : home_url('/maps/');

    wp_send_json_success([
        'user_id'  => $target_user_id,
        'email'    => $email,
        'company'  => $company,
        'location' => $location,
        'query'    => $query,
        'map_url'  => $map_url,
    ]);
}

add_action('wp_footer', function () {
    if (!is_user_logged_in()) {
        return;
    }
    $ajax_url = admin_url('admin-ajax.php');
    ?>
    <script>
    (function () {
        if (!window.location.pathname.includes('/messages')) return;
        const ajaxUrl = <?php echo wp_json_encode($ajax_url); ?>;
        let lastThreadKey = '';

        async function checkMessageShopInfo() {
            const match = window.location.pathname.match(/\/messages\/(?:thread\/)?(\d+)/);
            const threadId = match ? match[1] : '';
            const activeItem = document.querySelector('[data-thread-id].is-active, .bn-msg-thread[data-thread-id]');
            const tid = threadId || (activeItem ? activeItem.getAttribute('data-thread-id') : '');
            if (!tid || tid === lastThreadKey) return;
            lastThreadKey = tid;

            try {
                const body = new URLSearchParams({ action: 'pt_get_user_shop_info', thread_id: tid });
                const res = await fetch(ajaxUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: body.toString(),
                    credentials: 'same-origin',
                });
                const json = await res.json();
                if (!json || !json.success || !json.data) return;
                const { email, company, location, map_url, query } = json.data;
                if (!email && !company && !location) return;

                let bar = document.getElementById('pt-msg-shop-map-bar');
                const container = document.querySelector('.bn-msg-thread-header, .bn-msg-header, .bn-messages-main');
                if (!container) return;
                if (!bar) {
                    bar = document.createElement('div');
                    bar.id = 'pt-msg-shop-map-bar';
                    bar.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;font-size:13px;';
                    container.parentNode.insertBefore(bar, container.nextSibling);
                }
                const labelParts = [];
                if (company) labelParts.push('🏢 ' + company);
                if (location) labelParts.push('📍 ' + location);
                if (email) labelParts.push('✉️ ' + email);
                bar.innerHTML = '<span>' + labelParts.join(' &nbsp;|&nbsp; ') + '</span>' +
                    (query ? '<a href="' + map_url + '" target="_blank" style="background:#ef4444;color:#fff;padding:4px 10px;border-radius:6px;text-decoration:none;font-weight:600;">Tìm Shop trên Map</a>' : '');
            } catch (e) {}
        }

        document.addEventListener('click', () => setTimeout(checkMessageShopInfo, 300));
        setTimeout(checkMessageShopInfo, 600);
    })();
    </script>
    <?php
});

